function freshProject(){return {title:'Mi reforma',planName:'',planSrc:'',rooms:[],scale:124,scaleCalibrated:false,wallHeight:2.6,wallColor:'#e9e5dc',floorStyle:'wood',tasks:[],costs:[{name:'Pintura de paredes',unit:'m²',qtyType:'wall',price:''},{name:'Instalación de piso',unit:'m²',qtyType:'floor',price:''},{name:'Zócalos',unit:'m',qtyType:'length',price:''},{name:'Puertas y aberturas detectadas',unit:'ud',qtyType:'openings',price:''},{name:'Revestimiento de baño o cocina',unit:'m²',qtyType:'manual',qty:'',price:''}],finishes:{},documents:[],ocrText:'',style:'calido',selectedRoom:0,source:'empty'};}
let project;try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));project=saved&&saved.rooms&&saved.tasks?saved:freshProject();project.scaleCalibrated=project.scaleCalibrated===true;if(project.planSrc==='assets/tipo-a.png'){project={...project,title:project.title==='Apartamento Tipo A'?'Mi reforma':project.title,planName:'',planSrc:'',rooms:[],documents:(project.documents||[]).filter(d=>d.src!=='assets/tipo-a.png'),ocrText:'',source:'empty',manualWalls:null,selectedRoom:0};localStorage.setItem(STORE_KEY,JSON.stringify(project))}}catch{project=freshProject()}

function stableRoomId(){return globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():'room-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function migrateRoomIds(){for(const room of project.rooms||[]){if(!room.id)room.id=stableRoomId();for(const key of ['designDrafts','finishes']){project[key]=project[key]||{};if(project[key][room.name]&&!project[key][room.id]){project[key][room.id]=project[key][room.name];delete project[key][room.name]}}}}
migrateRoomIds();for(const document of project.documents||[])if(!document.id)document.id=stableRoomId();
