function renderFinishList(){const host=$('#finishList'),entries=project.rooms.map(room=>({room,x:project.finishes?.[roomKey(room)]})).filter(e=>e.x);$('#savedFinishCount').textContent=entries.length+' '+(entries.length===1?'estancia':'estancias');host.innerHTML=entries.length?entries.map(({room,x})=>`<article class="saved-finish-card"><span class="saved-finish-swatch" style="--swatch:${esc(x.color||'#ded7c9')}"></span><span class="saved-finish-copy"><b>${esc(room.name)}</b><small>${esc(x.styleName||x.style||'Estilo natural')} · ${esc(x.material||'Sin suelo')}</small><em>${esc(x.wallFinish||'Pared pintada')} · ${esc(roomType(room)==='bath'?(x.bath||'Baño por definir'):(x.wallName||'Color por definir'))}</em></span><button class="saved-open" data-open-finish="${esc(roomKey(room))}">Editar</button></article>`).join(''):'<div class="empty-state"><b>Aún no hay diseños guardados</b>Elige una habitación, combina materiales y guarda tu propuesta.</div>';$$('[data-open-finish]').forEach(b=>b.onclick=()=>{const index=project.rooms.findIndex(r=>roomKey(r)===b.dataset.openFinish);if(index>=0){project.selectedRoom=index;renderDesign();goView('design')}})}
function saveFinish(){checkpoint();if(!selectedRoom()){const pending=structuredClone(designDraft);createDesignRoom(false);designDraft=pending;storeDesignDraft();applyFinish();}const room=selectedRoom();if(!room)return;const style=styleOptions.find(s=>s.id===designDraft.style)||styleOptions[0],key=roomKey(room);project.finishes=project.finishes||{};project.finishes[key]={...structuredClone(designDraft),styleName:style.name,color:designDraft.wallColor,material:designDraft.material,style:style.id};project.designDrafts=project.designDrafts||{};project.designDrafts[key]=structuredClone(designDraft);renderFinishList();$('#selectionState').textContent='Diseño guardado';$('#selectionState').classList.add('saved');toast('Diseño guardado para '+room.name+'.');saveSoon()}
function suggestDesign(){checkpoint();const room=selectedRoom(),kind=roomType(room),areaM=room?Number(room.w)*Number(room.d):0;const wanted=kind==='bath'?'mediterraneo':kind==='bedroom'?'japandi':kind==='kitchen'?'contemporaneo':areaM<8?'nordico':'calido';const style=styleOptions.find(s=>s.id===wanted);designDraft.style=style.id;designDraft.wallColor=style.wall;designDraft.wallName=style.wallName;const floor=floorOptions.find(x=>x.name===style.floor);if(floor){designDraft.material=floor.name;designDraft.floorKind=floor.kind;designDraft.floorColor=floor.color}activeDesignCategory='estilo';renderDesign(true);$('#designTipTitle').textContent='Sugerencia para '+(room?.name||'tu estancia');applyFinish();storeDesignDraft();toast('Propuesta sugerida para '+(room?.name||'la estancia')+'.')}
function resetDesign(){checkpoint();designDraft=defaultDesign();storeDesignDraft();renderDesign();toast('Se restableció la propuesta de esta estancia.')}
function renderDocs(){const host=$('#documentGrid');$('#docCount').textContent=project.documents.length;host.innerHTML=project.documents.length?project.documents.map((d,i)=>{const src=docUrls.get(d.id)||d.src||'';return `<article class="doc-card"><div class="doc-preview">${d.kind==='image'&&src?`<img src="${esc(src)}" alt="Vista previa de ${esc(d.name)}">`:d.kind==='pdf'?'PDF':'▤'}</div><div class="doc-info"><b title="${esc(d.name)}">${esc(d.name)}</b><small>${esc(d.kind.toUpperCase())} · ${esc(d.date||'Archivo local')}${d.size?` · ${formatFileSize(d.size)}`:''}</small>${src?`<a class="doc-open" href="${esc(src)}" target="_blank" rel="noopener" download="${esc(d.name)}">Abrir / descargar ↗</a>`:'<small class="doc-unavailable">Archivo no disponible; vuelve a añadirlo</small>'}<button class="doc-remove" data-doc-remove="${i}">Quitar</button></div></article>`}).join(''):'<div class="empty-state"><b>Carpeta vacía</b>Añade planos, fotos y cotizaciones.</div>';$$('[data-doc-remove]').forEach(b=>b.onclick=()=>{const [removed]=project.documents.splice(+b.dataset.docRemove,1);if(removed){const url=docUrls.get(removed.id);if(url?.startsWith('blob:'))URL.revokeObjectURL(url);docUrls.delete(removed.id);removeDocumentFile(removed.id).catch(()=>{})}renderDocs();saveSoon()})}
function formatFileSize(bytes){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(0)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
function openDocumentDatabase(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB no disponible'));return}const request=indexedDB.open('homeai-project-files',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('documents'))request.result.createObjectStore('documents',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('No se pudo abrir el almacén local'))})}
async function storeDocumentFile(id,file){const db=await openDocumentDatabase();try{await new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').put({id,blob:file});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('No se pudo guardar el archivo'));tx.onabort=()=>reject(tx.error||new Error('Guardado cancelado'))})}finally{db.close()}return URL.createObjectURL(file)}
async function removeDocumentFile(id){const db=await openDocumentDatabase();try{await new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
async function hydrateDocumentFiles(){if(!('indexedDB'in window))return;const pending=project.documents.filter(d=>d.id&&!d.src&&!docUrls.has(d.id));if(!pending.length)return;const db=await openDocumentDatabase();try{await Promise.all(pending.map(d=>new Promise(resolve=>{const request=db.transaction('documents','readonly').objectStore('documents').get(d.id);request.onsuccess=()=>{if(request.result?.blob)docUrls.set(d.id,URL.createObjectURL(request.result.blob));resolve()};request.onerror=()=>resolve()})))}finally{db.close()}renderDocs()}
function exportObj(){const ppm=Number(project.scale)||124,vertices=[],faces=[],materials=[];let idx=1;vertices.push([0,0,0],[(maxX-minX)/ppm,0,0],[(maxX-minX)/ppm,(maxY-minY)/ppm,0],[0,(maxY-minY)/ppm,0]);faces.push({mat:'Suelo',fs:[[1,2,3,4]]});idx=5;function box(seg,thick,height,material){const dx=(seg.x2-seg.x1)/ppm,dy=-(seg.y2-seg.y1)/ppm,len=Math.hypot(dx,dy);if(len<.2)return;const nx=-dy/len*thick/2,ny=dx/len*thick/2,x1=(seg.x1-minX)/ppm,y1=(maxY-seg.y1)/ppm,x2=(seg.x2-minX)/ppm,y2=(maxY-seg.y2)/ppm;const p=[[x1+nx,y1+ny,0],[x2+nx,y2+ny,0],[x2-nx,y2-ny,0],[x1-nx,y1-ny,0],[x1+nx,y1+ny,height],[x2+nx,y2+ny,height],[x2-nx,y2-ny,height],[x1-nx,y1-ny,height]];p.forEach(v=>vertices.push(v));const base=idx;idx+=8;faces.push({mat:material,fs:[[base,base+1,base+5,base+4],[base+1,base+2,base+6,base+5],[base+2,base+3,base+7,base+6],[base+3,base,base+4,base+7],[base+4,base+5,base+6,base+7]]})}for(const s of wallSegments)box(s,.09,project.wallHeight,'Paredes');const obj=['# HomeAI · Maqueta conceptual desde plano','mtllib homeai-modelo.mtl','o Esquema_conceptual'];vertices.forEach(v=>obj.push('v '+v.map(x=>x.toFixed(4)).join(' ')));for(const f of faces){obj.push('usemtl '+f.mat);for(const q of f.fs)obj.push('f '+q.join(' '))}const mtl='newmtl Paredes\nKa 0.82 0.81 0.77\nKd 0.88 0.86 0.81\nKs 0.1 0.1 0.1\nNs 10\n\nnewmtl Suelo\nKa 0.72 0.66 0.55\nKd 0.76 0.68 0.54\nKs 0.04 0.04 0.04\nNs 8\n';download('homeai-esquema-conceptual.obj',new Blob([obj.join('\n')],{type:'text/plain'}));setTimeout(()=>download('homeai-esquema-conceptual.mtl',new Blob([mtl],{type:'text/plain'})),250);toast('Modelo OBJ y material MTL descargados.')}
function download(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function exportBudget(){const rows=[['Partida','Unidad','Cantidad','Precio unitario','Subtotal']];for(const x of project.costs){const q=costQuantity(x);rows.push([x.name,x.unit,q?fmt(q):'Pendiente',x.price||'',q&&x.price?fmt(q*Number(x.price)):''])}const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');download('homeai-presupuesto.csv',new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));}
function projectReport(){const rooms=project.rooms.map(r=>`<tr><td>${esc(r.name)}${r.verified===false?' · por confirmar':''}</td><td>${r.verified===false?'Pendiente de confirmar':fmt(r.w)+' × '+fmt(r.d)+' m'}</td><td>${r.verified===false?'—':fmt(area(r))+' m²'}</td></tr>`).join('');const todo=project.tasks.map(t=>`<li>${t.done?'☑':'☐'} ${esc(t.title)} — ${esc(t.phase)}${t.date?' · '+esc(t.date):''}${t.owner?' · '+esc(t.owner):''}</li>`).join('');const finishes=project.rooms.filter(r=>project.finishes?.[roomKey(r)]).map(r=>{const x=project.finishes[roomKey(r)];return `<tr><td>${esc(r.name)}</td><td>${esc(x.material)}</td><td>${esc(x.style)}</td><td><span style="display:inline-block;background:${esc(x.color)};width:18px;height:12px"></span> ${esc(x.color)}</td></tr>`}).join('');const docs=project.documents.map(d=>`<li>${esc(d.name)} · ${esc(d.kind)}</li>`).join('');return `<!doctype html><html lang="es"><meta charset="utf-8"><title>Proyecto de reforma · ${esc(project.title)}</title><style>body{font:14px Arial;color:#25352a;max-width:900px;margin:40px auto;padding:0 25px}h1{font:36px Georgia}h2{font:20px Georgia;margin-top:28px}p,td,li{line-height:1.6;color:#59655c}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}small{color:#899}.plan{max-width:100%;max-height:560px;object-fit:contain;display:block;margin:10px auto;border:1px solid #ddd}button{padding:10px 15px;background:#285541;color:white;border:0;border-radius:5px}@media print{button{display:none}body{margin:0 auto}}</style><p>HOMEAI · DOSSIER DEL PROYECTO</p><h1>${esc(project.title)}</h1><p>Documento de planificación · ${new Date().toLocaleDateString('es-ES')}</p><h2>Resumen</h2><p>${project.rooms.length?`${project.rooms.length} estancias · ${fmt(totalArea())} m² de área útil reconocida`:'Sin estancias medidas todavía'} · Altura de pared ${fmt(project.wallHeight)} m · ${fmt(calculateWallLength())} m de muros vectorizados</p><p>La maqueta 3D es conceptual; valida dimensiones, instalaciones y cantidades antes de contratar obra.</p>${project.planSrc?`<h2>Plano base</h2><img class="plan" src="${esc(project.planSrc)}" alt="Plano de referencia">`:''}<h2>Estancias medidas</h2><table><tr><th>Estancia</th><th>Dimensiones</th><th>Área</th></tr>${rooms}<tr><th>Total</th><th></th><th>${fmt(totalArea())} m²</th></tr></table><h2>Acabados elegidos</h2><table><tr><th>Estancia</th><th>Material</th><th>Estilo</th><th>Color</th></tr>${finishes||'<tr><td colspan="4">Sin acabados guardados todavía.</td></tr>'}</table><h2>Presupuesto</h2><p>${budgetTotal()?money(budgetTotal()):'Sin total: añade precios unitarios a las partidas.'}</p><table><tr><th>Partida</th><th>Precio unitario</th></tr>${project.costs.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.price?money(Number(x.price))+'/'+esc(x.unit):'precio pendiente'}</td></tr>`).join('')}</table><h2>Plan de obra</h2><ul>${todo}</ul><h2>Archivos del proyecto</h2><ul>${docs}</ul><p><small>Este dossier reúne los datos introducidos en HomeAI. El plano y la maqueta son orientativos y no sustituyen una medición profesional ni un presupuesto contractual.</small></p><button onclick="window.print()">Imprimir o guardar como PDF</button></html>`}
function openExportModal(){const m=$('#modal'),c=$('#modalContent');c.innerHTML=`<div class="crumb">EXPORTAR</div><h2>Comparte el avance del proyecto.</h2><p>Descarga un dossier para imprimir o conservar como PDF, una tabla CSV de presupuesto o el archivo 3D para abrirlo en una aplicación compatible.</p><button class="btn btn-dark full-width" id="makeReport">Abrir dossier para imprimir / guardar PDF</button><button class="btn btn-light full-width" id="makeCsv">Descargar presupuesto CSV</button><button class="btn btn-light full-width" id="makeObj">Descargar modelo 3D (.OBJ + .MTL)</button><button class="btn btn-light full-width" id="makeJson">Copia de seguridad del proyecto (.JSON)</button><hr style="border:none;border-top:1px solid var(--line);margin:18px 0"><p>¿Cambiaste de dispositivo o borraste el navegador? Restaura un archivo de copia de seguridad (.JSON) descargado antes.</p><button class="btn btn-light full-width" id="restoreJson">Restaurar copia de seguridad (.JSON)</button><input type="file" id="restoreJsonFile" accept="application/json,.json" hidden>`;m.classList.add('open');$('#makeReport').onclick=()=>{const w=window.open('','_blank');if(w){w.document.write(projectReport());w.document.close()}else toast('Permite ventanas emergentes para abrir el dossier.')};$('#makeCsv').onclick=exportBudget;$('#makeObj').onclick=exportObj;$('#makeJson').onclick=()=>download('homeai-proyecto.json',new Blob([JSON.stringify(project,null,2)],{type:'application/json'}));$('#restoreJson').onclick=()=>$('#restoreJsonFile').click();$('#restoreJsonFile').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)importProjectFromFile(file)}}
function importProjectFromFile(file){const reader=new FileReader();reader.onerror=()=>toast('No se pudo leer el archivo.');reader.onload=()=>{let data;try{data=JSON.parse(reader.result)}catch{toast('Ese archivo no es una copia de seguridad válida (JSON).');return}if(!data||!Array.isArray(data.rooms)||!Array.isArray(data.tasks)){toast('Ese archivo no tiene el formato de un proyecto de HomeAI.');return}if(!confirm('Esto sustituirá el proyecto actual en este dispositivo por el del archivo de copia de seguridad. ¿Continuar?'))return;data.scaleCalibrated=data.scaleCalibrated===true;project=data;undoStack=[];redoStack=[];if(!saveState())return;$('#modal').classList.remove('open');const img=$('#sourcePlan');if(project.planSrc){img.hidden=false;$('#planEmpty').classList.remove('visible');img.onload=()=>{detectWalls(img);renderAll();goView('overview');hydrateDocumentFiles().catch(()=>{});toast('Proyecto restaurado desde la copia de seguridad.')};img.onerror=()=>{fallbackWalls();renderAll();goView('overview');hydrateDocumentFiles().catch(()=>{});toast('Proyecto restaurado (no se pudo cargar la imagen del plano; vuelve a cargarlo).')};img.src=project.planSrc}else{img.hidden=true;img.removeAttribute('src');$('#planEmpty').classList.add('visible');fallbackWalls();renderAll();goView('overview');hydrateDocumentFiles().catch(()=>{});toast('Proyecto restaurado desde la copia de seguridad.')}};reader.readAsText(file)}
function analyzeLines(txt){const result=[];for(const line of txt.split(/\n/)){const m=line.match(/([\p{L}ÁÉÍÓÚÑáéíóúñ0-9 .'-]{2,50}?)\s*(\d{1,2}(?:[.,]\d{1,2})?)\s*[x×X]\s*(\d{1,2}(?:[.,]\d{1,2})?)\s*(?:m(?:etros?)?)?/u);if(m){const name=m[1].replace(/[|:;_]+/g,' ').trim().replace(/\s{2,}/g,' '),w=Number(m[2].replace(',','.')),d=Number(m[3].replace(',','.'));if(name.length>1&&w>.35&&d>.35&&w<30&&d<30)result.push({name:name.replace(/(^|[\s-])(\p{L})/gu,(_,prefix,ch)=>prefix+ch.toLocaleUpperCase('es')),w,d,color:'#d7cdbf'})}}return result}
async function loadTesseract(){if(window.Tesseract)return window.Tesseract;return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=()=>resolve(window.Tesseract);s.onerror=()=>reject(new Error('No se pudo cargar el motor de lectura.'));document.head.appendChild(s)})}
async function analyzePlan(){const img=$('#sourcePlan');if(!img.complete||!img.naturalWidth){toast('Carga un plano para analizar.');return}if(ocrBusy)return;ocrBusy=true;$('#planStatus').innerHTML='<i></i> La IA está leyendo el plano';$('#aiMessage').textContent='Cargando lectura de texto en español…';try{const T=await loadTesseract();ocrWorker=await T.createWorker('spa',1,{logger:m=>{if(m.status==='recognizing text')$('#aiMessage').textContent='IA leyendo etiquetas: '+Math.round(m.progress*100)+'%'}});const res=await ocrWorker.recognize(img);const text=res.data.text||'';project.ocrText=text;$('#ocrText').textContent=text||'No se encontró texto legible.';const parsed=analyzeLines(text);if(parsed.length>=1){const used=new Set();const merged=project.rooms.map(r=>{const j=parsed.findIndex((x,k)=>!used.has(k)&&x.name.toLowerCase().includes(r.name.toLowerCase().split(' ')[0]));if(j>=0){used.add(j);return {...r,w:parsed[j].w,d:parsed[j].d,verified:false,source:'ocr'}}return r});const extra=parsed.filter((_,i)=>!used.has(i)).map(r=>({...r,id:stableRoomId(),verified:false,source:'ocr'}));project.rooms=[...merged,...extra];linkRoomsToWalls();renderRooms();updateProjectNumbers();$('#aiMessage').textContent=`OCR encontró ${parsed.length} posibles medidas. Confirma cada una en la tabla para incluirla en superficies.`;toast(parsed.length+' posibles medidas. Confirma las correctas en la tabla.')}else{$('#aiMessage').textContent='El OCR no encontró medidas completas en una misma línea. Revisa el texto y añade las dimensiones manualmente.';toast('Lectura completada; comprueba el texto reconocido.')}$('#planStatus').innerHTML='<i></i> Lectura completada';await ocrWorker.terminate();ocrWorker=null;saveSoon()}catch(e){$('#aiMessage').textContent='No se pudo cargar el lector IA. Puedes editar la tabla manualmente.';$('#planStatus').innerHTML='<i></i> Edición manual disponible';toast('La lectura IA no está disponible ahora; puedes continuar manualmente.')}finally{ocrBusy=false}}
function createDesignRoom(showToast=true,requestedName='',requestedType=''){const preferred=['Salón','Dormitorio','Cocina','Baño','Comedor','Terraza'];const used=new Set(project.rooms.map(room=>room.name));const name=requestedName||preferred.find(value=>!used.has(value))||`Estancia ${project.rooms.length+1}`,room={id:stableRoomId(),name,type:requestedType||roomKind(name),w:'',d:'',verified:false,color:'#d7cdbf'};project.rooms.push(room);project.selectedRoom=project.rooms.length-1;project.designDrafts=project.designDrafts||{};project.designDrafts[room.id]=structuredClone(defaultDesign());linkRoomsToWalls();renderRooms();updateProjectNumbers();renderDesign();saveSoon();if(showToast)toast(`${name} añadida. Puedes diseñarla y medirla más adelante.`);return room}
function addRoom(){project.rooms.push({id:stableRoomId(),name:'Nueva estancia',w:'',d:'',verified:false,color:'#d7cdbf'});linkRoomsToWalls();renderRooms();updateProjectNumbers();const input=$$('.room-name-input').at(-1);input?.focus();saveSoon()}
function addCost(){project.costs.push({name:'Nueva partida',unit:'ud',qtyType:'manual',qty:'',price:''});renderBudget();saveSoon()}
function addTask(){const name=prompt('Nombre de la nueva tarea');if(!name?.trim())return;project.tasks.push({title:name.trim(),phase:'Tareas adicionales',done:false,date:'',owner:''});renderTasks();renderOverview();saveSoon()}
function exportMoodboard(){const lines=[['Estancia','Estilo','Color de pared','Acabado de pared','Suelo','Conjunto de baño','Grifería','Mobiliario','Iluminación','Textiles','Cortinas','Alfombras','Almacenaje','Detalles','Herrajes','Ducha o bañera','Lavabo y mueble','Sanitarios','Almacenaje de baño'].join(';'),...Object.entries(project.finishes||{}).map(([room,x])=>[project.rooms.find(r=>roomKey(r)===room)?.name||room,x.styleName||x.style,x.wallName||x.color,x.wallFinish,x.material,x.bath,x.faucet,x.decor?.furniture,x.decor?.lighting,x.decor?.textiles,x.decor?.curtains,x.decor?.rugs,x.decor?.storage,x.decor?.accessories,x.decor?.hardware,x.bathDetails?.shower,x.bathDetails?.vanity,x.bathDetails?.sanitary,x.bathDetails?.storage].map(v=>'"'+String(v||'').replace(/"/g,'""')+'"').join(';'))];download('homeai-acabados.csv',new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}))}
function addDocument(){const f=$('#documentFile');f.click()}
async function handleDocument(file){if(!file)return;const kind=file.type==='application/pdf'?'pdf':file.type.startsWith('image/')?'image':'file',entry={id:stableRoomId(),name:file.name,kind,date:new Date().toLocaleDateString('es-ES'),size:file.size};try{docUrls.set(entry.id,await storeDocumentFile(entry.id,file))}catch{if(file.size>=500000){toast('No se pudo guardar este archivo en el dispositivo. No se ha añadido.');return}try{entry.src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}catch{toast('No se pudo leer el archivo. Inténtalo de nuevo.');return}}project.documents.unshift(entry);renderDocs();saveSoon();toast('Archivo guardado en este dispositivo.')}
function planDataUrl(file){return new Promise((resolve,reject)=>{const fallback=()=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)};if(file.size<900000){fallback();return}const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const max=2400,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{URL.revokeObjectURL(url);if(!blob){fallback();return}const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)},'image/jpeg',.88)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);fallback()};img.src=url})}
async function changePlan(file){if(!file)return;if(!file.type.startsWith('image/')){toast('Usa una captura PNG, JPG o WebP del plano.');return}$('#planStatus').innerHTML='<i></i> Preparando el plano';try{const src=await planDataUrl(file);project.planSrc=src;project.planName=file.name;project.source='user';loadPlan(src,file.name);renderDocs()}catch{toast('No se pudo preparar la imagen. Intenta con otra copia del plano.');$('#planStatus').innerHTML='<i></i> Esperando plano'}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function undo(){if(!undoStack.length)return toast('No hay cambios anteriores.');redoStack.push(JSON.stringify(project));project=JSON.parse(undoStack.pop());renderAll();saveSoon()}
function redo(){if(!redoStack.length)return toast('No hay cambios para rehacer.');undoStack.push(JSON.stringify(project));project=JSON.parse(redoStack.pop());renderAll();saveSoon()}
function checkpoint(){undoStack.push(JSON.stringify(project));if(undoStack.length>20)undoStack.shift();redoStack=[]}
function renderAll(){if(Array.isArray(project.manualWalls)){wallSegments=structuredClone(project.manualWalls);updateWallBounds()}else if($('#sourcePlan').naturalWidth)detectWalls($('#sourcePlan'));renderWallEditor();renderRooms();renderBudget();renderTasks();renderDocs();renderOverview();renderModelRoomList();renderDesign();$('#projectTitle').value=project.title;$('#pixelsPerMeter').value=project.scale;$('#wallHeight').value=project.wallHeight;$('#wallHeightLabel').textContent=fmt(project.wallHeight)+' m';$('#planName').textContent=project.planName||'Plano de referencia';renderModel();renderMini()}
function on(el,ev,fn){$(el).addEventListener(ev,fn)}
function startDesignFromHub(inspiration=false){const name=$('#startRoomType').value,kind=roomKind(name),match=project.rooms.findIndex(r=>roomType(r)===kind);if(match<0)createDesignRoom(false,name,kind);else project.selectedRoom=match;goView('design');document.querySelector(inspiration?'[data-photo-tab="concept"]':'[data-photo-tab="photo"]')?.click();saveSoon()}
function bind(){addNavHandlers();$$('[data-setup-go]').forEach(b=>b.onclick=()=>goView(b.dataset.setupGo));$('#setupContinue').onclick=()=>goView($('#setupContinue').dataset.target||'plan');$('#catalogSearch').oninput=filterCatalog;$('#clearCatalogSearch').onclick=()=>{$('#catalogSearch').value='';filterCatalog();$('#catalogSearch').focus()};$('#projectTitle').oninput=()=>{project.title=$('#projectTitle').value;renderOverview();saveSoon()};$('#saveProject').onclick=()=>{if(saveState())toast('Proyecto guardado en este dispositivo.')};$('#exportProject').onclick=openExportModal;$('#undoAction').onclick=undo;$('#redoAction').onclick=redo;$('#uploadPlan').onclick=()=>$('#planFile').click();$('#planFile').onchange=e=>changePlan(e.target.files[0]);$('#planDrop').ondragover=e=>{e.preventDefault();$('#planDrop').style.outline='2px dashed #608366'};$('#planDrop').ondragleave=()=>$('#planDrop').style.outline='';$('#planDrop').ondrop=e=>{e.preventDefault();$('#planDrop').style.outline='';changePlan(e.dataTransfer.files[0])};$('#pixelsPerMeter').onchange=()=>{checkpoint();project.scale=Math.max(10,Number($('#pixelsPerMeter').value)||124);project.scaleCalibrated=true;$('#scaleStatus').textContent='Ajustada manualmente';renderModel();renderBudget();renderOverview();saveSoon()};$('#analyzePlan').onclick=analyzePlan;$('#calibrateScale').onclick=()=>{if(!project.planSrc){toast('Carga primero el plano de tu vivienda.');return}if(!(Number($('#knownDistance').value)>0)){toast('Escribe primero la longitud que aparece en el plano.');$('#knownDistance').focus();return}scaleCalMode=true;wallEditMode=false;$('#wallEditor').classList.add('active');$('#traceTip').classList.add('active');$('#traceTip').textContent='2 · Arrastra exactamente sobre la línea que mide '+$('#knownDistance').value+' m';$('#calibrateScale').classList.add('active');toast('Introduce la cota real y traza esa misma distancia sobre el plano.')};$('#buildModel').onclick=()=>{if(!project.planSrc&&!project.rooms.length){toast('Carga un plano real o añade estancias antes de generar el modelo.');return}renderModel();goView('model');toast('Esquema conceptual generado; revisa su distribución y medidas.')};$('#addRoom').onclick=addRoom;$('#wallHeight').oninput=()=>{project.wallHeight=Number($('#wallHeight').value);$('#wallHeightLabel').textContent=fmt(project.wallHeight)+' m';renderModel();renderBudget();renderOverview();saveSoon()};$('#resetCamera').onclick=()=>{modelYaw=-.62;modelPitch=.78;modelZoom=1;renderModel()};$('#cameraTop').onclick=()=>{modelYaw=0;modelPitch=.14;renderModel()};$('#toggleWallEdit').onclick=toggleWallEdit;$('#resetWalls').onclick=()=>{project.manualWalls=null;wallEditMode=false;$('#wallEditor').classList.remove('active');$('#traceTip').classList.remove('active');$('#toggleWallEdit').classList.remove('active');detectWalls($('#sourcePlan'));toast('Paredes recuperadas desde el plano.');saveSoon()};setupWallEditor();$('#toggleDimensions').onclick=()=>{showDimensions=!showDimensions;$('#toggleDimensions').classList.toggle('active',showDimensions);renderModel()};$('#toggleWire').onclick=()=>{wireMode=!wireMode;$('#toggleWire').classList.toggle('active',wireMode);renderModel()};$('#wallPalette').innerHTML=colorOptions.map(([color,name])=>`<button class="color-dot ${project.wallColor===color?'active':''}" title="${name}" style="background:${color}" data-wall-color="${color}"></button>`).join('');$$('[data-wall-color]').forEach(b=>b.onclick=()=>{project.wallColor=b.dataset.wallColor;$$('[data-wall-color]').forEach(x=>x.classList.toggle('active',x===b));renderModel();saveSoon()});$$('[data-floor]').forEach(b=>{b.classList.toggle('selected',b.dataset.floor===project.floorStyle);b.onclick=()=>{project.floorStyle=b.dataset.floor;$$('[data-floor]').forEach(x=>x.classList.toggle('selected',x===b));renderModel();renderMini();saveSoon()}});$('#exportObj').onclick=exportObj;$('#designRoomSelect').onchange=()=>{project.selectedRoom=Number($('#designRoomSelect').value);renderDesign()};$('#addDesignRoom').onclick=()=>createDesignRoom(true);$('#startDesignNow').onclick=()=>startDesignFromHub(false);$('#startInspirationNow').onclick=()=>startDesignFromHub(true);$('#saveSelection').onclick=saveFinish;$('#exportMoodboard').onclick=exportMoodboard;$('#addCost').onclick=addCost;$('#exportBudget').onclick=exportBudget;$('#addTask').onclick=addTask;$('#addDocument').onclick=addDocument;$('#documentFile').onchange=e=>handleDocument(e.target.files[0]);$('#closeModal').onclick=()=>$('#modal').classList.remove('open');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('open')};$('#helpBtn').onclick=()=>{const m=$('#modal'),c=$('#modalContent');c.innerHTML='<div class="crumb">HOMEAI · ESTUDIO DE REFORMA</div><h2>Del plano al plan de obra.</h2><p><b>1 · Sube o revisa el plano.</b> La lectura IA usa OCR en español para reconocer nombres y medidas impresas; comprueba cada dato.</p><p><b>2 · Genera el modelo.</b> La vista 3D detecta líneas oscuras del plano y las extruye a la altura elegida. Es conceptual: comprueba la distribución y calibra la escala antes de usar cantidades.</p><p><b>3 · Completa el proyecto.</b> Guarda acabados por estancia, añade precios y organiza tareas. Exporta un dossier, presupuesto CSV, copia JSON o geometría OBJ/MTL.</p><p><b>Privacidad:</b> tus datos se quedan en este navegador. La primera lectura descarga un motor OCR en español, pero el plano no se envía a un servidor.</p>';m.classList.add('open')};$('#miniCanvas').addEventListener('pointerdown',()=>goView('model'));$('#modelCanvas').addEventListener('pointerdown',e=>{dragging=true;lastPointer={x:e.clientX,y:e.clientY};$('#modelCanvas').setPointerCapture(e.pointerId)});$('#modelCanvas').addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastPointer.x,dy=e.clientY-lastPointer.y;modelYaw+=dx*.009;modelPitch=Math.max(.08,Math.min(1.35,modelPitch+dy*.006));lastPointer={x:e.clientX,y:e.clientY};renderModel()});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>$('#modelCanvas').addEventListener(ev,()=>{dragging=false}));$('#modelCanvas').addEventListener('wheel',e=>{e.preventDefault();modelZoom=Math.max(.55,Math.min(1.8,modelZoom*(e.deltaY>0?.92:1.08)));renderModel()},{passive:false});window.addEventListener('resize',()=>{renderModel();renderMini()});$('#currency').value=project.currency||defaultCurrency();$('#currency').onchange=()=>{project.currency=$('#currency').value;renderBudget();renderOverview();saveSoon()};$('#addTask').onclick=addTask;}
function bindDesignControls(){
 $('#suggestDesign').onclick=suggestDesign;$('#resetDesign').onclick=resetDesign;$('#nextDesignStep').onclick=()=>{const index=designStages.findIndex(item=>item.id===activeDesignCategory);if(index<0||index>=designStages.length-1)return;const next=designStages[index+1];$('#catalogSearch').value='';setDesignCategory(next.id);filterCatalog();$('#tab-'+next.id).focus({preventScroll:true})};
 $('#compareDesign').onclick=()=>{compareMode=!compareMode;$('#designPreview').classList.toggle('compare-mode',compareMode);$('#compareDesign').setAttribute('aria-pressed',String(compareMode));$('#compareDesign').textContent=compareMode?'Volver a la propuesta':'Comparar con base neutra'};
}
function init(){$('#projectTitle').value=project.title||'Mi reforma';$('#scaleStatus').textContent=project.scaleCalibrated?'Escala calibrada':'Pendiente de calibrar';if(project.planSrc){$('#sourcePlan').hidden=false;$('#sourcePlan').src=project.planSrc}else{$('#sourcePlan').hidden=true;$('#sourcePlan').removeAttribute('src');$('#planEmpty').classList.add('visible');fallbackWalls()}$('#sourcePlan').onload=()=>{detectWalls($('#sourcePlan'));renderAll()};$('#sourcePlan').onerror=()=>{if(project.planSrc)fallbackWalls();renderAll()};if(project.planSrc&&$('#sourcePlan').complete&&$('#sourcePlan').naturalWidth){detectWalls($('#sourcePlan'));renderAll()}else{renderRooms();renderBudget();renderTasks();renderDocs();renderOverview();renderModel();renderMini()}bind();bindDesignControls();renderDesign();hydrateDocumentFiles().catch(()=>{});if('serviceWorker'in navigator&&location.hostname!=='terminal.local'&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init();
